import math

def kl_report(p, q):
    """{"bits": D(p || q) in bits, "nats": the same in nats}; math.inf for both if q_i = 0 < p_i."""
    nats = 0.0
    for pi, qi in zip(p, q):
        if pi == 0:
            continue
        if qi == 0:
            return {"bits": math.inf, "nats": math.inf}
        nats += pi * math.log(pi / qi)
    return {"bits": nats / math.log(2), "nats": nats}

