import math

def held_out_loss(train_counts, test_counts, alpha):
    n, k, m = sum(train_counts), len(train_counts), sum(test_counts)
    loss = 0.0
    for tr, te in zip(train_counts, test_counts):
        if te == 0:
            continue
        q = (tr + alpha) / (n + k * alpha)
        if q == 0:
            return math.inf
        loss -= te / m * math.log(q)
    return loss

def best_smoothing(train_counts, test_counts, alphas):
    """The alpha whose add-alpha model of train_counts has the least
    cross-entropy on test_counts; the smallest such alpha on a tie."""
    return min(alphas, key=lambda a: (held_out_loss(train_counts, test_counts, a), a))

